Sample=[(360:830)',cqsrfls15];

%calculate XYZWT and XYZT
[XYZT,XYZWT]=spd2xyz(S1,2,0,Sample);

CCT=CCTa(XYZWT);T=CCT;

%calculate reference illuminant
Sr=CCT2CIEref(CCT,lambda);

if nargin == 3; Sr=[interpK(Sr(:,1),Sr(:,2),lambda,'v5cubic')];Sr=[lambda,Sr./(sum(Sr).*abs(lambda(1)-lambda(2)))];Sr(isnan(Sr(:,2)),2)=0;end

%calculate XYZR and XYZWR
[XYZR,XYZWR]=spd2xyz(Sr,2,0,Sample);

%calc corresponding colours of munsell under D65
XYZTc=xyz2xyzc(XYZT,XYZWT,XYZWR,1000,1000);
XYZWTc=xyz2xyzc(XYZWT,XYZWT,XYZWR,1000,1000);

LABt=xyz2lab(XYZTc,XYZWTc);
LABr=xyz2lab(XYZR,XYZWR);

%--------adjusted code-----------------------------------------------------
%correct metric calculation for possible missing samples
[usesamples,Nsamples]=selectsampleswithinhueintervalthetas(thetas,Sample,2);%select samples within hue interval
LABr=LABr(usesamples,:);
LABt=LABt(usesamples,:);
if sum(usesamples)==Nsamples
    %keep original cfactors
else
    %use new scaling parameters
    cfactor_a=scalingpars.a;
    cfactor_f=scalingpars.f;
    cfactor_p=scalingpars.p;
end
%--------end adjusted code-------------------------------------------------

LAB_Ct=sqrt(LABt(:,2).^2+LABt(:,3).^2);%LAB_ht=atan(LABt(:,3)./LABt(:,2));
LAB_Cr=sqrt(LABr(:,2).^2+LABr(:,3).^2);%LAB_hr=atan(LABr(:,3)./LABr(:,2));
         
deltaLstar=(LABt(:,1)-LABr(:,1));
deltaastar=(LABt(:,2)-LABr(:,2));
deltabstar=(LABt(:,3)-LABr(:,3));
deltaE=sqrt(deltaLstar.^2+deltaastar.^2+deltabstar.^2);%calculate individual deltaE's

deltaC=LAB_Ct-LAB_Cr;
deltaEf=deltaE;%save for Qf;
deltaCo=deltaC;
maxC=10;
deltaC(deltaC>=maxC)=maxC;%limit Chroma increase!
deltaE(deltaC>0)=sqrt(deltaE(deltaC>0).^2-deltaC(deltaC>0).^2);%increase in chroma is not penalized!


deltaERMS=sqrt(sum(deltaE.^2)./numel(deltaE)); %take RMS average for Qa
deltaERMSf=sqrt(sum(deltaEf.^2)./numel(deltaEf));%take RMS average for Qf

%calculate relative Gamut area Qg
Qg=100.*polyarea(LABt(:,2),LABt(:,3))./polyarea(LABr(:,2),LABr(:,3));

GA=1; %no CCT-factor!!!!
Qai=(100-deltaE.*cfactor_a);
Qai=GA.*log(exp(Qai./10)+1).*10;
if size(Qai(:,1))==1;Qai=Qai';end
DERMS=deltaERMS;
Qa=(100-deltaERMS.*cfactor_a);
Qa=GA.*log(exp(Qa/10)+1).*10;
dERMSa=deltaERMS;

%colour fidelity
Qf=(100-deltaERMSf.*cfactor_f);
Qf=GA.*log(exp(Qf/10)+1).*10;
dERMSf=deltaERMSf;

%colour preference
deltaCmu=mean(deltaC.*(deltaC>=0));
Qp=100-cfactor_p.*(deltaERMS-deltaCmu);
Qp=GA.*log(exp(Qp/10)+1).*10;
dERMSp=deltaERMS-deltaCmu;

DErms=[dERMSa,dERMSf,dERMSp];

end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function XYZc=xyz2xyzc(XYZ,XYZtw,XYZrw,Lt,Lr);
%CMCCAT
MCAT=[0.7982,	0.3389,	-0.1371;
        -0.5918,	1.5512,	0.0406;
        0.0008,	0.0239,	0.9753];

MCATi=inv(MCAT);

%degree of adaptation
D=0.08*log10(Lt+Lr)+0.76-0.45*(Lt-Lr)/(Lt+Lr);
if D>1;D=1;end

Y=XYZ(2);

XYZ=XYZ./XYZ(2);
XYZtw=XYZtw./XYZtw(2);
XYZrw=XYZrw./XYZrw(2);


% Convert XYZ data to CAT02 LMS space
RGB=(MCAT*XYZ')';
R=RGB(:,1);G=RGB(:,2);B=RGB(:,3);

RGBtw=(MCAT*XYZtw')';
RGBrw=(MCAT*XYZrw')';
Rtw=RGBtw(:,1);Gtw=RGBtw(:,2);Btw=RGBtw(:,3);
Rrw=RGBrw(:,1);Grw=RGBrw(:,2);Brw=RGBrw(:,3);

% Apply chromatic adaptation (
Rc=(D.*(Rrw./Rtw)+1-D).*R;
Gc=(D.*(Grw./Gtw)+1-D).*G;
Bc=(D.*(Brw./Btw)+1-D).*B;

RGBc=[Rc,Gc,Bc];

% Calculate XYZ
XYZc=(MCATi*[Rc,Gc,Bc]')';
XYZc=XYZc.*Y;

end
